ALTER TABLE portal_credentials_vault ADD COLUMN IF NOT EXISTS session_cookies TEXT;
ALTER TABLE portal_credentials_vault ADD COLUMN IF NOT EXISTS profile_review_url TEXT;
ALTER TABLE portal_credentials_vault ADD COLUMN IF NOT EXISTS profile_approval_status TEXT DEFAULT 'NOT_FILLED';
ALTER TABLE portal_credentials_vault ADD COLUMN IF NOT EXISTS profile_completed_at TIMESTAMPTZ;
ALTER TABLE portal_credentials_vault ADD COLUMN IF NOT EXISTS profile_approved_at TIMESTAMPTZ;
ALTER TABLE portal_credentials_vault ADD COLUMN IF NOT EXISTS custom_preferences_note TEXT;

DELETE FROM learned_rules a USING learned_rules b
WHERE a.id > b.id AND a.section_name = b.section_name AND a.rule_instruction = b.rule_instruction;

SELECT
  (SELECT row_to_json(f) FROM (
     SELECT role_category, sample_summary_html, sample_skills_html, sample_experience_html
     FROM role_few_shot_library
     ORDER BY id ASC LIMIT 1
   ) f) AS master_archetype,
  (SELECT COALESCE(json_agg(r), '[]'::json) FROM (
     SELECT id, section_name, role_category, rule_instruction
     FROM learned_rules
     WHERE is_active = TRUE AND LOWER(section_name) NOT LIKE '%cover%' AND LOWER(section_name) <> 'cl'
     ORDER BY id DESC LIMIT 20
   ) r) AS active_rules,
  (SELECT COALESCE(json_agg(v), '[]'::json) FROM (
     SELECT site_name, portal_url, profile_review_url, login_method, auth_email, communication_email,
            username, encrypted_password, auth_status, profile_approval_status,
            profile_completed_at, profile_approved_at, custom_preferences_note
     FROM portal_credentials_vault
     ORDER BY site_name ASC
   ) v) AS vault_rows;

