const skillsRows = $('Read Skills Tab').all().map(i => i.json);
const certsRows = $('Read Certifications Tab').all().map(i => i.json);
const sitesRows = $('Read Site Application Tracker').all().map(i => i.json);
const pg = $('Postgres: Load Authenticated Portals').first().json || {};

const arch = pg.master_archetype || {};
const activeRules = Array.isArray(pg.active_rules) ? pg.active_rules : [];
const vaultRows = Array.isArray(pg.vault_rows) ? pg.vault_rows : [];

const skillsByCat = {};
const allSkills = [];
for (const r of skillsRows) {
  const cat = String(r['Category'] || 'Core Analytics').trim();
  const sk = String(r['Skill Name'] || r['Skills'] || '').trim();
  if (!sk) continue;
  allSkills.push(sk);
  if (!skillsByCat[cat]) skillsByCat[cat] = [];
  skillsByCat[cat].push(sk);
}

const certsList = certsRows
  .map(r => {
    const name = String(r['Name of the Certification'] || '').trim();
    const provider = String(r['Provider'] || 'Coursera').trim();
    const date = String(r['Date/Month of Completion'] || '').trim();
    return name ? `<div class="cert-row"><span class="cert-name">${provider} - ${name}</span><span class="cert-date">${date}</span></div>` : '';
  })
  .filter(Boolean)
  .join('\n');

const summaryHtml = arch.sample_summary_html || `<p>Customer &amp; Marketing Analytics Manager with 8+ years of experience driving revenue growth, retention, and BI automation across FinTech, E-Commerce, and Enterprise SaaS using SQL, Python, Tableau, and Power BI.</p>`;

const skillsHtml = arch.sample_skills_html || (
  `<ul>` +
  Object.entries(skillsByCat).slice(0, 5).map(([cat, list]) => `<li><strong>${cat}:</strong> ${list.join(', ')}</li>`).join('\n') +
  `</ul>`
);

const experienceHtml = arch.sample_experience_html || `<p>Experience details loaded from Master Archetype.</p>`;
const educationHtml = `<div class="edu-row"><span>University of Delhi, B.Comm(Hons.)</span><span class="edu-date">2013 – 2016</span></div>`;
const hobbiesHtml = `<div class="hobbies-line">Practicing Buddhism &nbsp;|&nbsp; Automating life with n8n &nbsp;|&nbsp; Growing Mushrooms</div>`;

const cssStyles = `
  @page { size: A4; margin: 0.44in 0.50in; }
  * { box-sizing: border-box; }
  body { font-family: 'Georgia', 'Times New Roman', serif; font-size: 10.1pt; line-height: 1.35; color: #111111; margin: 0; padding: 0; }
  .resume-header { text-align: center; margin-bottom: 9px; }
  .resume-header h1 { font-size: 24pt; font-weight: normal; margin: 0 0 3px 0; letter-spacing: 0.3px; }
  .contact-line { font-size: 9.8pt; color: #222222; }
  .contact-line a { color: #111111; text-decoration: none; }
  .section-title { font-size: 11.8pt; font-weight: bold; border-bottom: 1px solid #1A365D; padding-bottom: 2px; margin-top: 9px; margin-bottom: 5px; color: #1A365D; }
  p { margin: 0 0 5px 0; text-align: left; }
  ul { margin: 2px 0 6px 0; padding-left: 18px; }
  li { margin-bottom: 3px; }
  strong { font-weight: bold; color: #000000; }
  .job-block { margin-bottom: 7px; page-break-inside: avoid; break-inside: avoid; }
  .job-header, .cert-row, .edu-row { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 2px; }
  .job-header, .job-title, .job-date { font-weight: bold; color: #000000; }
  .job-date, .cert-date, .edu-date { white-space: nowrap; font-size: 9.8pt; }
  .hobbies-line { margin-top: 3px; font-size: 10pt; }
`;

const fullHtml = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <title>Sumanto_Banerjee-Master_Resume</title>
  <style>${cssStyles}</style>
</head>
<body>
  <div class="resume-header">
    <h1>Sumanto Banerjee</h1>
    <div class="contact-line">user@example.com &nbsp;|&nbsp; +91-8802444912 &nbsp;|&nbsp; <a href="https://www.linkedin.com/in/sumanto-banerjee/">Linkedin Profile</a></div>
  </div>
  <div class="section-title">Summary</div>
  ${summaryHtml}
  <div class="section-title">Core Skills</div>
  ${skillsHtml}
  <div class="section-title">Experience</div>
  ${experienceHtml}
  <div class="section-title">Certifications</div>
  ${certsList}
  <div class="section-title">Education</div>
  ${educationHtml}
  <div class="section-title">When I am not analysing...</div>
  ${hobbiesHtml}
</body>
</html>`;

return [{
  json: {
    pdfFileName: 'Sumanto_Banerjee-Master_Resume.pdf',
    skillsCount: allSkills.length,
    certsCount: certsRows.length,
    rulesCount: activeRules.length,
    recentRules: activeRules.slice(-4).map(r => r.rule_instruction),
    sitesCount: sitesRows.length
  },
  binary: {
    index_html: await this.helpers.prepareBinaryData(Buffer.from(fullHtml, 'utf8'), 'index.html', 'text/html')
  }
}];

let triggerInput = {};
try {
  if ($('On-Demand Telegram Trigger').isExecuted) {
    triggerInput = $('On-Demand Telegram Trigger').first()?.json || {};
  }
} catch (e) {}
const silentBgSync = Boolean(triggerInput.silentBgSync);
const forceReviewPortal = String(triggerInput.forceReviewPortal || '').trim();

const meta = $('Compile Master Resume HTML').first().json || {};
const driveOut = $('Upload Master Resume PDF to Google Drive').first().json || {};
const driveLink = driveOut.webViewLink || 'https://drive.google.com/file/d/YOUR_GOOGLE_DRIVE_ID';
const driveId = driveOut.id || '1Ddz2BDGVJk_0RyhF9jEcQ4vGyNvU4dt1';

const sitesRows = $('Read Site Application Tracker').all().map(i => i.json);
const skillsRows = $('Read Skills Tab').all().map(i => i.json);
const certsRows = $('Read Certifications Tab').all().map(i => i.json);
const pg = $('Postgres: Load Authenticated Portals').first().json || {};
const vaultRows = Array.isArray(pg.vault_rows) ? pg.vault_rows : [];

const todayStr = new Date().toISOString().slice(0, 10);

const normalizeSite = (s) => {
  const raw = String(s || '').trim().toLowerCase();
  if (raw === 'linkedin' || raw === 'linkedin jobs') return 'linkedin jobs';
  if (raw === 'ycombinator' || raw === 'y combinator') return 'y combinator';
  if (raw === 'hirist') return 'hirist';
  return raw;
};

const PROFILE_REVIEW_URLS = {
  'naukri': 'https://www.naukri.com/mnjuser/profile',
  'linkedin jobs': 'https://www.linkedin.com/jobs/application-settings/',
  'wellfound': 'https://wellfound.com/u/edit',
  'indeed': 'https://profile.indeed.com/',
  'y combinator': 'https://www.workatastartup.com/application',
  'naukri gulf': 'https://www.naukrigulf.com/jobseeker/my-profile',
  'monster': 'https://www.monster.com/profile/detail',
  'hirist': 'https://www.hirist.tech/jobseeker/profile',
  'foundit (monster)': 'https://www.foundit.in/seeker/profile',
  'times jobs': 'https://www.timesjobs.com/candidate/myprofile.html',
  'shine': 'https://www.shine.com/myshine/myprofile/',
  'glassdoor': 'https://www.glassdoor.co.in/member/profile/index.htm',
  'testgorilla': 'https://app.testgorilla.com/candidate/profile',
  'careerbuilder': 'https://www.careerbuilder.com/profile',
  'himalayas': 'https://himalayas.app/dashboard/profile',
  'weworkremotely': 'https://weworkremotely.com/job-seekers/account/edit',
  'remotive': 'https://remotive.com/my-account',
  'working nomads': 'https://www.workingnomads.com/users/edit',
  'instahyre': 'https://www.instahyre.com/candidate/profile/',
  'cutshort': 'https://cutshort.io/profile/candidate-profile',
  'jobgether': 'https://jobgether.com/app/profile',
  'builtin (remote & india)': 'https://builtin.com/profile',
  'remoteok': 'https://remoteok.com/settings'
};

function getProfileReviewUrl(siteName, fallbackUrl) {
  const norm = normalizeSite(siteName);
  return PROFILE_REVIEW_URLS[norm] || fallbackUrl || 'https://docs.google.com/spreadsheets/d/YOUR_GOOGLE_DOCUMENT_ID/edit';
}

const vaultMap = {};
for (const v of vaultRows) {
  vaultMap[normalizeSite(v.site_name)] = v;
}

const allSkillNames = skillsRows.map(s => String(s['Skill Name'] || s.Skill || '').trim()).filter(Boolean);
const allCertNames = certsRows.map(c => `${c['Name of the Certification'] || ''} (${c['Provider'] || 'Coursera'})`.trim()).filter(Boolean);

const baseProfileBundle = {
  headline: 'Senior Data Analyst & BI Specialist | Data Modelling, Python, SQL, Tableau & AI Automation | 5+ Yrs Exp',
  communication_email: 'user@example.com',
  master_resume_pdf: driveLink,
  master_resume_file_id: driveId,
  skills_synced: allSkillNames,
  certifications_synced: allCertNames,
  career_preferences: {
    target_roles: ['Senior Data Analyst', 'Business Intelligence Analyst', 'Analytics Engineer', 'Product Analyst', 'Analytics Manager', 'BI Lead'],
    preferred_regions: ['EU (DE/NL/IE/UK - Visa Sponsorship & Remote)', 'Australia', 'Global Remote', 'UAE / Middle East', 'India (Gurugram, Bengaluru, Noida, Hyderabad, Mumbai, Remote)'],
    work_modes: ['Remote', 'Hybrid', 'On-site (Open to Relocation)'],
    notice_period: 'Immediate / 15-30 Days'
  },
  synced_at: new Date().toISOString()
};

const sheetUpdates = [];
const sqlStatements = [];
const approvedSites = [];
const pendingReviewSites = [];
const pausedSites = [];
const pendingAuthSites = [];

const esc = (s) => String(s || '').replace(/'/g, "''");

for (const row of sitesRows) {
  const siteName = String(row['Site'] || '').trim();
  if (!siteName) continue;
  const norm = normalizeSite(siteName);
  const v = vaultMap[norm] || {};
  const sheetAuth = String(row['Authentication Status'] || '').trim();
  const vaultAuth = String(v.auth_status || '').trim();

  const isAuth =
    sheetAuth.toLowerCase().startsWith('authenticated') ||
    vaultAuth.toLowerCase().startsWith('authenticated');

  const portalUrl = String(row['Portal / Search URL'] || v.portal_url || '').trim();
  const profileReviewUrl = getProfileReviewUrl(siteName, portalUrl);
  const loginMethod = v.login_method || (sheetAuth.includes('Google SSO') ? 'Google SSO (008)' : (isAuth ? 'Logged In Session' : 'Pending Setup'));
  const authEmail = v.auth_email || 'user@example.com';
  const customNote = String(v.custom_preferences_note || '').trim();

  if (isAuth) {
    let approvalStatus = String(v.profile_approval_status || '').trim();
    if (forceReviewPortal && normalizeSite(forceReviewPortal) === norm) {
      approvalStatus = 'PENDING_REVIEW';
    } else if (approvalStatus === 'APPROVED') {
      approvalStatus = 'APPROVED';
    } else if (approvalStatus === 'PAUSED') {
      approvalStatus = 'PAUSED';
    } else {
      approvalStatus = 'PENDING_REVIEW';
    }

    const portalBundle = {
      ...baseProfileBundle,
      portal_name: siteName,
      profile_review_url: profileReviewUrl,
      custom_preferences_note: customNote || undefined,
      profile_approval_status: approvalStatus
    };

    let statusBadge = '';
    if (approvalStatus === 'APPROVED') {
      statusBadge = `Authenticated (${loginMethod}) | ✅ Profile Approved (Auto-Apply Active)`;
      approvedSites.push({ siteName, profileReviewUrl, portalUrl, loginMethod });
    } else if (approvalStatus === 'PAUSED') {
      statusBadge = `Authenticated (${loginMethod}) | ⏸️ Profile On Hold (Auto-Apply Paused)`;
      pausedSites.push({ siteName, profileReviewUrl, portalUrl, loginMethod });
    } else {
      statusBadge = `Authenticated (${loginMethod}) | ⏳ Profile Pending Review (Auto-Apply Locked)`;
      pendingReviewSites.push({ siteName, profileReviewUrl, portalUrl, loginMethod, customNote });
    }

    sheetUpdates.push({
      Site: siteName,
      'Updated Resume': `Uploaded - Sumanto_Banerjee-Master_Resume.pdf (${todayStr})`,
      'Skills Updated': `Filled (${meta.skillsCount || allSkillNames.length} Skills + ${meta.certsCount || allCertNames.length} Certs + EU/AU/Global Prefs - ${todayStr})`,
      'Region / Remote Focus': 'EU, Australia, Global Remote, UAE & India',
      'Authentication Status': statusBadge
    });

    sqlStatements.push(
      `INSERT INTO portal_credentials_vault (site_name, portal_url, profile_review_url, login_method, auth_email, communication_email, auth_status, profile_approval_status, profile_completed_at, session_cookies, updated_at) ` +
      `VALUES ('${esc(siteName)}', '${esc(portalUrl)}', '${esc(profileReviewUrl)}', '${esc(loginMethod)}', '${esc(authEmail)}', 'user@example.com', 'Authenticated', '${esc(approvalStatus)}', NOW(), '${esc(JSON.stringify(portalBundle))}', NOW()) ` +
      `ON CONFLICT (site_name) DO UPDATE SET ` +
      `portal_url = EXCLUDED.portal_url, ` +
      `profile_review_url = EXCLUDED.profile_review_url, ` +
      `auth_status = 'Authenticated', ` +
      `profile_approval_status = '${esc(approvalStatus)}', ` +
      `profile_completed_at = COALESCE(portal_credentials_vault.profile_completed_at, NOW()), ` +
      `session_cookies = EXCLUDED.session_cookies, ` +
      `updated_at = NOW();`
    );
  } else {
    pendingAuthSites.push(siteName);
    sqlStatements.push(
      `INSERT INTO portal_credentials_vault (site_name, portal_url, profile_review_url, login_method, auth_email, communication_email, auth_status, profile_approval_status, updated_at) ` +
      `VALUES ('${esc(siteName)}', '${esc(portalUrl)}', '${esc(profileReviewUrl)}', 'Google SSO (008)', 'user@example.com', 'user@example.com', 'Authentication pending', 'NOT_FILLED', NOW()) ` +
      `ON CONFLICT (site_name) DO UPDATE SET ` +
      `portal_url = COALESCE(NULLIF(EXCLUDED.portal_url, ''), portal_credentials_vault.portal_url), ` +
      `profile_review_url = EXCLUDED.profile_review_url, ` +
      `profile_approval_status = CASE WHEN LOWER(portal_credentials_vault.auth_status) LIKE 'authenticated%' THEN portal_credentials_vault.profile_approval_status ELSE 'NOT_FILLED' END, ` +
      `updated_at = NOW();`
    );
  }
}

sqlStatements.push(`DELETE FROM portal_credentials_vault WHERE site_name IN ('LinkedIn', 'YCombinator', 'Hirist');`);

sqlStatements.push(
  `INSERT INTO master_resume_state (id, drive_file_id, drive_web_link, rules_applied_count, skills_count, certs_count, updated_at) ` +
  `VALUES (1, '${esc(driveId)}', '${esc(driveLink)}', ${meta.rulesCount || 0}, ${meta.skillsCount || allSkillNames.length}, ${meta.certsCount || allCertNames.length}, NOW()) ` +
  `ON CONFLICT (id) DO UPDATE SET drive_file_id = EXCLUDED.drive_file_id, drive_web_link = EXCLUDED.drive_web_link, rules_applied_count = EXCLUDED.rules_applied_count, skills_count = EXCLUDED.skills_count, certs_count = EXCLUDED.certs_count, updated_at = NOW();`
);

const TG_TOKEN = 'YOUR_TELEGRAM_BOT_TOKEN';
const ADMIN_CHAT_ID = '8873019272';

if (!silentBgSync) {
  const reviewLines = pendingReviewSites.map(p =>
    `• *${p.siteName}* — [🔍 Check & Review Profile](${p.profileReviewUrl}) | [Jobs Page](${p.portalUrl || p.profileReviewUrl})\n` +
    `  _Filled: Master Resume PDF + ${meta.skillsCount || 29} Skills + ${meta.certsCount || 3} Certs + EU/AU/Remote/India Prefs_`
  ).join('\n\n') || '• _None awaiting review_';

  const approvedLines = approvedSites.map(p =>
    `• *${p.siteName}* — ` + '`🟢 Approved (Auto-Apply Active)`' + ` ([Profile](${p.profileReviewUrl}))`
  ).join('\n') || '• _None approved yet (Approve below to unlock Auto-Apply!)_';

  const tgText =
    `🛠️ *Portal Profiles Filled, Master Resume Uploaded & Preferences Updated!*\n` +
    `━━━━━━━━━━━━━━━━━━━━━━━━\n` +
    `📄 *Uploaded Master Resume:* [Sumanto_Banerjee-Master_Resume.pdf](${driveLink})\n` +
    `🎯 *Preferences Set:* \`Senior Data Analyst / BI / Analytics Engineer\` • \`EU, Australia, Global Remote, UAE & India\` • \`Remote / Hybrid\`\n` +
    `📧 *Comm Email:* \`user@example.com\`\n\n` +
    `⏳ *1. Portals Waiting for Your Review & Approval (${pendingReviewSites.length}) — Auto-Apply LOCKED:*\n` +
    `${reviewLines}\n\n` +
    `🟢 *2. Approved Portals (${approvedSites.length}) — Auto-Apply UNLOCKED:*\n` +
    `${approvedLines}\n\n` +
    `🟡 *3. Portals Pending Initial Login (${pendingAuthSites.length} of ${sitesRows.length})*\n\n` +
    `👉 _Click the profile review link(s) above to verify your profile, resume & preferences. Once satisfied, tap **✅ Approve** below to start applying to jobs!_`;

  const kb = [];
  for (const p of pendingReviewSites) {
    kb.push([
      { text: `✅ Approve ${p.siteName} & Start Applying`, callback_data: `prof_app:${p.siteName}` },
      { text: `✏️ Edit ${p.siteName}`, callback_data: `prof_edit:${p.siteName}` }
    ]);
  }
  if (pendingReviewSites.length > 1) {
    kb.push([{ text: `✅ Approve ALL ${pendingReviewSites.length} Profiles & Start Applying`, callback_data: 'prof_app_all' }]);
  }
  kb.push([{ text: `👤 Portal Profile Review Queue (${pendingReviewSites.length} Pending)`, callback_data: 'cmd:profile_reviews' }]);
  kb.push([{ text: `🔐 Manage All ${sitesRows.length} Portals (${pendingAuthSites.length} Need Login)`, callback_data: 'cred_list:all:0' }]);
  kb.push([{ text: '🏠 Back to Compact Menu', callback_data: 'nav:home' }]);

  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: `https://api.telegram.org/bot${TG_TOKEN}/sendMessage`,
      headers: { 'Content-Type': 'application/json' },
      body: {
        chat_id: ADMIN_CHAT_ID,
        text: tgText,
        parse_mode: 'Markdown',
        disable_web_page_preview: true,
        reply_markup: { inline_keyboard: kb }
      },
      json: true
    });
  } catch (e) {}
}

const outItems = sheetUpdates.length > 0
  ? sheetUpdates.map((u, idx) => ({
      json: {
        ...u,
        sqlBatch: idx === 0 ? sqlStatements.join('\n') : 'SELECT 1;'
      }
    }))
  : [{
      json: {
        Site: 'Naukri',
        'Updated Resume': `Uploaded - Sumanto_Banerjee-Master_Resume.pdf (${todayStr})`,
        'Skills Updated': `Filled (${meta.skillsCount} Skills + ${meta.certsCount} Certs - ${todayStr})`,
        'Region / Remote Focus': 'EU, Australia, Global Remote, UAE & India',
        'Authentication Status': `Authenticated | ⏳ Profile Pending Review (Auto-Apply Locked)`,
        sqlBatch: sqlStatements.join('\n')
      }
    }];

return outItems;
